// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice Gas optimized Merkle proof verification library.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/MerkleProofLib.sol)
library MerkleProofLib {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                  MERKLE PROOF OPERATIONS                   */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Verifies a Merkle proof by computing the root hash from the provided proof and leaf.
    ///
    /// @param proof An array of bytes32 values representing the Merkle proof.
    /// @param root The expected root hash of the Merkle tree.
    /// @param leaf The leaf node to verify against the Merkle proof.
    /// @return isValid A boolean indicating whether the computed root matches the provided root.
    function verify(bytes32[] memory proof, bytes32 root, bytes32 leaf)
        internal
        pure
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            if mload(proof) {
                let p := add(proof, 0x20)
                let e := add(p, shl(5, mload(proof)))
                for {} 1 {} {
                    let a := mload(p)
                    let b := leaf
                    if gt(a, b) { let t := a a := b b := t }
                    mstore(0x00, a)
                    mstore(0x20, b)
                    leaf := keccak256(0x00, 0x40)
                    p := add(p, 0x20)
                    if iszero(lt(p, e)) { break }
                }
            }
            isValid := eq(leaf, root)
        }
    }

    /// @notice Verifies a Merkle proof by reconstructing the root hash from the provided proof and leaf.
    ///
    /// @param proof An array of bytes32 representing the Merkle proof.
    /// @param root The expected root hash of the Merkle tree.
    /// @param leaf The leaf node to be verified against the root.
    /// @return isValid A boolean indicating whether the reconstructed root matches the provided root.
    function verifyCalldata(bytes32[] calldata proof, bytes32 root, bytes32 leaf)
        internal
        pure
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            if proof.length {
                let e := add(proof.offset, shl(5, proof.length))
                for {} 1 {} {
                    calldatacopy(0x00, proof.offset, 0x20)
                    let a := mload(0x00)
                    let b := leaf
                    if gt(a, b) { let t := a a := b b := t }
                    mstore(0x00, a)
                    mstore(0x20, b)
                    leaf := keccak256(0x00, 0x40)
                    proof.offset := add(proof.offset, 0x20)
                    if iszero(lt(proof.offset, e)) { break }
                }
            }
            isValid := eq(leaf, root)
        }
    }

    /// @notice Verifies a multi-proof for a Merkle tree using a given set of leaves, proof, and flags.
    ///
    /// @param proof An array of proof elements used to verify the Merkle tree.
    /// @param root The root of the Merkle tree to verify against.
    /// @param leaves An array of leaves to be verified.
    /// @param flags An array of boolean flags indicating whether to pop from the queue or the proof.
    /// @return isValid A boolean indicating whether the multi-proof is valid.
    function verifyMultiProof(
        bytes32[] memory proof,
        bytes32 root,
        bytes32[] memory leaves,
        bool[] memory flags
    ) internal pure returns (bool isValid) {
        /// @solidity memory-safe-assembly
        assembly {
            let proofLen := mload(proof)
            let leavesLen := mload(leaves)
            let flagsLen := mload(flags)
            proof := add(proof, 0x20)
            leaves := add(leaves, 0x20)
            flags := add(flags, 0x20)

            if eq(add(leavesLen, proofLen), add(flagsLen, 1)) {
                if iszero(flagsLen) {
                    if eq(leavesLen, 1) {
                        isValid := eq(mload(leaves), root)
                    }
                    if eq(leavesLen, 0) {
                        isValid := iszero(or(iszero(root), proofLen))
                        if isValid {
                            isValid := eq(mload(proof), root)
                        }
                    }
                }
                if iszero(iszero(flagsLen)) {
                    let hashesLen := add(flagsLen, 1)
                    let hashes := mload(0x40)
                    mstore(hashes, leavesLen)
                    let flagsEnd := add(flags, shl(5, flagsLen))
                    let h := add(hashes, 0x20)
                    let j := 0
                    for {} lt(j, leavesLen) { j := add(j, 1) } {
                        mstore(h, mload(add(leaves, shl(5, j))))
                        h := add(h, 0x20)
                    }
                    mstore(0x40, h)
                    let hp := add(hashes, 0x20)
                    let pp := proof
                    let fp := flags
                    for {} lt(fp, flagsEnd) {} {
                        let flag := mload(fp)
                        fp := add(fp, 0x20)
                        let a := mload(hp)
                        if iszero(flag) {
                            a := mload(pp)
                            pp := add(pp, 0x20)
                        }
                        hp := add(hp, 0x20)
                        let b := mload(hp)
                        if flag {
                            b := mload(pp)
                            pp := add(pp, 0x20)
                        }
                        if gt(a, b) { let t := a a := b b := t }
                        mstore(0x00, a)
                        mstore(0x20, b)
                        mstore(hp, keccak256(0x00, 0x40))
                    }
                    isValid := and(eq(mload(hp), root), eq(pp, add(proof, shl(5, proofLen))))
                }
            }
        }
    }

    /// @notice Verifies a Merkle multi-proof using calldata for efficiency.
    ///
    /// @param proof An array of Merkle proof elements.
    /// @param root The Merkle root to verify against.
    /// @param leaves An array of leaf nodes to verify.
    /// @param flags An array of boolean flags indicating whether to pop from the queue or the proof.
    /// @return isValid A boolean indicating whether the proof is valid.
    function verifyMultiProofCalldata(
        bytes32[] calldata proof,
        bytes32 root,
        bytes32[] calldata leaves,
        bool[] calldata flags
    ) internal pure returns (bool isValid) {
        /// @solidity memory-safe-assembly
        assembly {
            let proofLen := proof.length
            let leavesLen := leaves.length
            let flagsLen := flags.length

            if eq(add(leavesLen, proofLen), add(flagsLen, 1)) {
                if iszero(flagsLen) {
                    if eq(leavesLen, 1) {
                        calldatacopy(0x00, leaves.offset, 0x20)
                        isValid := eq(mload(0x00), root)
                    }
                    if eq(leavesLen, 0) {
                        isValid := iszero(or(iszero(root), proofLen))
                        if isValid {
                            calldatacopy(0x00, proof.offset, 0x20)
                            isValid := eq(mload(0x00), root)
                        }
                    }
                }
                if iszero(iszero(flagsLen)) {
                    let flagsEnd := add(flags.offset, shl(5, flagsLen))
                    let hashes := mload(0x40)
                    mstore(hashes, leavesLen)
                    let h := add(hashes, 0x20)
                    let j := 0
                    for {} lt(j, leavesLen) { j := add(j, 1) } {
                        calldatacopy(h, add(leaves.offset, shl(5, j)), 0x20)
                        h := add(h, 0x20)
                    }
                    mstore(0x40, h)
                    let hp := add(hashes, 0x20)
                    let pp := proof.offset
                    let fp := flags.offset
                    for {} lt(fp, flagsEnd) {} {
                        let flag := calldataload(fp)
                        fp := add(fp, 0x20)
                        let a := mload(hp)
                        if iszero(flag) {
                            a := calldataload(pp)
                            pp := add(pp, 0x20)
                        }
                        hp := add(hp, 0x20)
                        let b := mload(hp)
                        if flag {
                            b := calldataload(pp)
                            pp := add(pp, 0x20)
                        }
                        if gt(a, b) { let t := a a := b b := t }
                        mstore(0x00, a)
                        mstore(0x20, b)
                        mstore(hp, keccak256(0x00, 0x40))
                    }
                    isValid := and(
                        eq(mload(hp), root),
                        eq(pp, add(proof.offset, shl(5, proofLen)))
                    )
                }
            }
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    EMPTY ARRAY HELPERS                     */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Returns an empty proof array.
    function emptyProof() internal pure returns (bytes32[] calldata proof) {
        /// @solidity memory-safe-assembly
        assembly {
            proof.length := 0
        }
    }

    /// @notice Returns an empty array of `bytes32` leaves.
    function emptyLeaves() internal pure returns (bytes32[] calldata leaves) {
        /// @solidity memory-safe-assembly
        assembly {
            leaves.length := 0
        }
    }

    /// @notice Returns an empty array of boolean flags.
    function emptyFlags() internal pure returns (bool[] calldata flags) {
        /// @solidity memory-safe-assembly
        assembly {
            flags.length := 0
        }
    }
}

